package mrpapermoon.whisper.meshimport android.content.Contextimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.CoroutineExceptionHandlerimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.ObsoleteCoroutinesApiimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.channels.actorimport kotlinx.coroutines.launchimport kotlinx.coroutines.plusimport mrpapermoon.whisper.mesh.db.RumorDatabaseimport mrpapermoon.whisper.mesh.nearby.EndpointConnectionHolderimport mrpapermoon.whisper.service.NearbyConnectionsAdapterimport java.util.concurrent.ConcurrentHashMapinterface MeshNetworkManager {	suspend fun awaitIsReady()	companion object {		fun create(			context: Context,			coroutineContext: CoroutineExceptionHandler,			uuid: String,		): MeshNetworkManager = MeshNetworkManagerImpl(context, coroutineContext, uuid, byteArrayOf())	}}@OptIn(ObsoleteCoroutinesApi::class)internal class MeshNetworkManagerImpl(	context: Context,	coroutineContext: CoroutineExceptionHandler,	uuid: String,	cipher: ByteArray,) : MeshNetworkManager {	private val database by lazy { RumorDatabase.getDatabase(context) }	private val scope = CoroutineScope(coroutineContext + SupervisorJob())	private val connectionsAdapter = NearbyConnectionsAdapter.getConnectionsAdapter(context, scope + Dispatchers.IO, uuid)	private val logger = KotlinLogging.logger {}	init {		val connectionsHolderMap = ConcurrentHashMap<String, EndpointConnectionHolder>()		scope.launch(Dispatchers.Default) {			connectionsAdapter.collect { event ->				val endpointId = event.endpointId				val connectionHolder = connectionsHolderMap					.computeIfAbsent(endpointId) {						logger.debug { "New connection(endpointId: $endpointId, event :$event)" }						val actor = (scope + Dispatchers.Unconfined).actor {							for (message in channel) {								connectionsAdapter.sendPayloadBytes(endpointId, message)							}						}						EndpointConnectionHolder(actor, cipher, database, endpointId)					}				runCatching {					connectionHolder.onEvent(event)				}					.onFailure {						if (it is EndpointConnectionHolder.ConnectionComplete) {							logger.debug { "On data sharing complete(endpointId: $endpointId)" }							connectionsHolderMap.remove(endpointId)						} else {							logger.error(it) { "On data sharing error" }							throw it						}					}			}		}	}	override suspend fun awaitIsReady() {		connectionsAdapter.startConnection()		database	}}